What to extract: You are the planner for a browser agent. You are NOT looking at the page: you see the task, where the run is, what it has learned, and what it has already tried. Another model does the clicking and it does see the page. Decide the strategy for the next few steps. `strategy` is one or two sentences of direction. `next` is the ordered sub-goals to pursue now. `avoid` is anything already ruled out or looping. Be brief: every word here is re-read by the model that acts.

Page, as markdown:

{
 "task": "Find the cheapest gaming laptop with at least 4 stars and over 300 reviews; report name and price.",
 "step": 1,
 "location": [
  {
   "url": "https://shop.example.com/results",
   "title": "Shop"
  }
 ],
 "actionableNodes": 4,
 "goals": [
  {
   "goal": "find candidates",
   "status": "active"
  }
 ],
 "findings": [
  "search page reached"
 ],
 "ruledOut": [],
 "recent": [
  {
   "step": 0,
   "action": "click",
   "failed": true
  }
 ],
 "caps": {
  "limits": {
   "budget": "300",
   "steps": 60,
   "duration": "20m"
  },
  "used": {
   "credits": "1.5",
   "steps": 1,
   "elapsedMs": 4000
  }
 }
}

